 manuscript_not_found:{zh:'稿件或版本不存在，请重新读取。',en:'The manuscript or version is unavailable. Reload its details.'},
 manuscript_source_limit:{zh:'写作资料最多支持50项来源（统计、图表和报告分别计数），请选择较小的汇总报告。',en:'Writing materials support at most 50 sources. Analyses, figures and reports count separately. Select a smaller collection report.'},
 manuscript_review_blocked:{zh:'稿件存在不可豁免的来源、数值或引用一致性问题，请核对评审结果。',en:'The manuscript has blocking source, numeric or citation consistency issues. Review the assessment results.'},
 manuscript_review_input_invalid:{zh:'稿件评审输入无效，请核对基础版本和所选资料。',en:'The manuscript review input is invalid. Review the base version and selected materials.'},
 manuscript_review_not_found:{zh:'稿件评审不存在，请重新读取。',en:'The manuscript review is unavailable. Reload its details.'},
 manuscript_revision_conflict:{zh:'稿件已有新版本，请读取最新版本后核对。',en:'A newer manuscript version exists. Load the latest version and review it.'},
 manuscript_writing_input_limit:{zh:'完整写作外发包超过输入上限，请减少所选材料后重新预览；未作截断。',en:'The complete outbound writing bundle exceeds the input limit. Reduce the selected materials and preview again. No truncation was performed.'},
 manuscript_writing_language_invalid:{zh:'全文语言审核未通过完整性、图内文字、内容身份或科学审核边界校验，请核对审核结果。',en:'The full-text language review failed completeness, figure-text, content-identity or scientific-review boundary checks. Review its results.'},
 manuscript_writing_language_required:{zh:'审后候选尚未完成全文语言核验，请先完成语言审核。',en:'The reviewed candidate has not completed full-text language verification. Complete its language review first.'},
 manuscript_writing_material_blocked:{zh:'所选文字含本地路径、不支持的链接或凭据样式，请移除后重新预览。',en:'The selected text contains local paths, unsupported links or credential-like content. Remove them and preview again.'},
 manuscript_writing_review_invalid:{zh:'科学审核、文本匹配、数值绑定或非目标内容保留校验失败，请核对审核结果。',en:'Scientific review, text matching, numeric binding or preservation of non-target content failed validation. Review the assessment results.'},
 manuscript_writing_review_required:{zh:'请在受控写作工作区核对成功的 v2 原始候选，并完成精确文本科学审核与全文语言审核后再发布。',en:'In the controlled writing workspace, verify a successful original v2 candidate and complete exact-text scientific review and full-text language review before publishing.'},
 manuscript_writing_selection_invalid:{zh:'只能选择当前冻结版本中的来源和证据，请重新核对选择。',en:'Only sources and evidence from the current frozen version can be selected. Review the selection.'},
