 storage_deletion_scope_unknown:{zh:'无法确认资料是否涉及已处置范围，请核对来源后再操作。',en:'It is unclear whether the material belongs to a disposed scope. Verify its sources before continuing.'},
 storage_policy_invalid:{zh:'存储配额参数或修改理由无效，请核对后再保存。',en:'The storage quota parameters or change reason are invalid. Review them before saving.'},
 storage_reservation_conflict:{zh:'存储操作与已有预留或产物冲突，请核对原操作和产物状态。',en:'The storage operation conflicts with an existing reservation or artifact. Review the original operation and artifact status.'},
 literature_pmc_not_authorized:{zh:'尚未授权 PMC 获取，请核对授权登记。',en:'PMC retrieval has not been authorized. Review its authorization record.'},
 review_continuation_invalid:{zh:'下一轮输入与明确选择的上一轮或回传稿不匹配，请核对来源。',en:'The next-round input does not match the selected previous round or returned manuscript. Review its sources.'},
 review_document_export_not_found:{zh:'独立文档导出不存在，请重新读取。',en:'The independent document export is unavailable. Reload its details.'},
 review_document_export_not_ready:{zh:'独立文档导出尚未成功，请先核对原任务状态。',en:'The independent document export is not ready. Check the original task status.'},
 review_document_not_found:{zh:'独立文档不存在，请重新读取。',en:'The independent document is unavailable. Reload its details.'},
 review_progress_correction_conflict:{zh:'该进展已有纠正，请读取最新记录后核对。',en:'This progress entry already has a correction. Load the latest entry and review it.'},
 review_progress_invalid:{zh:'进展关联的轮次、稿件或导出无效，请核对明确选择的来源。',en:'The progress references an invalid round, manuscript or export. Review the selected sources.'},
 review_return_blocked:{zh:'回传仍有受保护内容或匹配问题，原稿与输入均已保留。',en:'The return has unresolved protected-content or matching issues. The original manuscript and input are retained.'},
 review_return_invalid:{zh:'回传输入与明确选择的父稿或修改结果不匹配，请核对来源。',en:'The returned input does not match the selected parent manuscript or revision. Review its sources.'},
 review_return_preview_conflict:{zh:'回传差异预览已变化，请重新查看并确认。',en:'The returned-manuscript preview has changed. Review and confirm it again.'},
 review_revision_not_ready:{zh:'实际修改或公共新稿尚未成功，请核对原任务。',en:'The revision or published manuscript is not ready. Check the original task.'},
