 admin_last_active: {"zh": "必须保留至少一名启用的管理员。", "en": "At least one active administrator must remain."},
 admin_revision_conflict: {"zh": "账号已被修改，请读取最新版本后重试。", "en": "The account changed. Load its latest revision and retry."},
 admin_user_not_found: {"zh": "账号不存在，请刷新账号列表。", "en": "The account no longer exists. Refresh the account list."},
 admin_change_invalid: {"zh": "账号变更无效，请修改角色或状态并填写有效理由。", "en": "The account change is invalid. Change its role or active status and provide a meaningful reason."},
