  pdf_input_invalid:{zh:"DOCX 输入未通过 PDF 转换检查，请核对来源并联系管理员。",en:"The DOCX input failed PDF conversion checks. Verify the source and contact the administrator."},
  pdf_renderer_mismatch:{zh:"文档排版环境与固定版本不一致，请联系管理员核对。",en:"The document layout environment differs from the fixed version. Contact the administrator."},
  literature_supplement_limit:{zh:'该论述已使用一轮补搜（最多20篇），请继续已有任务。',en:'This claim already has one supplementary search (up to 20 candidates). Continue the existing task.'},
